values
  (1, 'Kupovina', 'Stan', 'Trosoban stan sa pogledom na reku', 'Beograd, Novi Beograd', 44.8133, 20.4183, 185000, 74, 3, 'Svetao trosoban stan na višem spratu, sa velikom dnevnom sobom i pogledom na reku. Prostorije su funkcionalno raspoređene, a prevoz i prodavnice su na nekoliko minuta hoda.', $json${"Sprat":"9 / 14","Grejanje":"Centralno","Godina izgradnje":2016,"Parking":"Garažno mesto"}$json$::jsonb, $json$[{"src":"/demo/city.jpg","position":"17% 45%","zoom":2.4},{"src":"/demo/city.jpg","position":"50% 60%","zoom":1},{"src":"/demo/city.jpg","position":"93% 38%","zoom":2.6},{"src":"/demo/city.jpg","position":"54% 42%","zoom":2.6},{"src":"/demo/city.jpg","position":"70% 92%","zoom":2.2}]$json$::jsonb, '2026-10-28'::timestamptz),
  (2, 'Kupovina', 'Kuća', 'Porodična kuća sa dvorištem', 'Niš, Medijana', 43.312, 21.931, 240000, 165, 5, 'Prostrana porodična kuća sa uređenim dvorištem i garažom. Prizemlje čine dnevna soba, trpezarija i kuhinja, a spavaće sobe su na spratu.', $json${"Spratnost":"Pr + 1","Grejanje":"Etažno na gas","Godina izgradnje":2019,"Parking":"Garaža"}$json$::jsonb, $json$[{"src":"/demo/house.jpg","position":"50% 62%","zoom":1.15},{"src":"/demo/house.jpg","position":"48% 42%","zoom":2},{"src":"/demo/house.jpg","position":"76% 72%","zoom":2.2},{"src":"/demo/house.jpg","position":"28% 78%","zoom":2.2},{"src":"/demo/house.jpg","position":"60% 90%","zoom":1.6}]$json$::jsonb, '2026-10-22'::timestamptz),
  (3, 'Kupovina', 'Stan', 'Dvosoban stan u novogradnji', 'Novi Sad, Liman', 45.2372, 19.839, 128000, 52, 2, 'Moderan dvosoban stan u novoj zgradi sa liftom. Odličan izbor za mlade parove ili kao investicija, u blizini keja i fakulteta.', $json${"Sprat":"3 / 6","Grejanje":"Centralno","Godina izgradnje":2025,"Parking":"Spoljno mesto"}$json$::jsonb, $json$[{"src":"/demo/city.jpg","position":"54% 42%","zoom":2.6},{"src":"/demo/city.jpg","position":"50% 60%","zoom":1},{"src":"/demo/city.jpg","position":"93% 38%","zoom":2.6},{"src":"/demo/city.jpg","position":"54% 42%","zoom":2.6},{"src":"/demo/city.jpg","position":"70% 92%","zoom":2.2}]$json$::jsonb, '2026-11-02'::timestamptz),
  (4, 'Kupovina', 'Kuća', 'Kuća sa garažom za dva vozila', 'Kragujevac, Centar', 44.0132, 20.9196, 198000, 140, 4, 'Lepo održavana kuća blizu centra grada, sa dvostrukom garažom i pristupom sa mirne ulice. Spremna je za useljenje.', $json${"Spratnost":"Pr + 1","Grejanje":"Etažno na gas","Godina izgradnje":2014,"Parking":"Garaža za dva vozila"}$json$::jsonb, $json$[{"src":"/demo/house.jpg","position":"28% 78%","zoom":2.2},{"src":"/demo/house.jpg","position":"48% 42%","zoom":2},{"src":"/demo/house.jpg","position":"76% 72%","zoom":2.2},{"src":"/demo/house.jpg","position":"28% 78%","zoom":2.2},{"src":"/demo/house.jpg","position":"60% 90%","zoom":1.6}]$json$::jsonb, '2026-10-15'::timestamptz),
  (5, 'Kupovina', 'Stan', 'Četvorosoban stan na visokom spratu', 'Beograd, Vračar', 44.7979, 20.4722, 310000, 96, 4, 'Komforan četvorosoban stan sa panoramskim pogledom na grad. Ima dva kupatila, zasebnu kuhinju i veliku terasu.', $json${"Sprat":"15 / 20","Grejanje":"Centralno","Godina izgradnje":2020,"Parking":"Garažno mesto"}$json$::jsonb, $json$[{"src":"/demo/city.jpg","position":"93% 38%","zoom":2.6},{"src":"/demo/city.jpg","position":"50% 60%","zoom":1},{"src":"/demo/city.jpg","position":"93% 38%","zoom":2.6},{"src":"/demo/city.jpg","position":"54% 42%","zoom":2.6},{"src":"/demo/city.jpg","position":"70% 92%","zoom":2.2}]$json$::jsonb, '2026-10-30'::timestamptz),
  (6, 'Kupovina', 'Kuća', 'Dvospratna kuća u mirnom kraju', 'Niš, Pantelej', 43.34, 21.9158, 215000, 150, 5, 'Kuća na dva nivoa u tihom delu grada, sa puno prirodnog svetla i malim dvorištem. Pogodna za veću porodicu.', $json${"Spratnost":"Pr + 1","Grejanje":"Etažno na gas","Godina izgradnje":2012,"Parking":"Dvorište"}$json$::jsonb, $json$[{"src":"/demo/house.jpg","position":"48% 42%","zoom":2},{"src":"/demo/house.jpg","position":"48% 42%","zoom":2},{"src":"/demo/house.jpg","position":"76% 72%","zoom":2.2},{"src":"/demo/house.jpg","position":"28% 78%","zoom":2.2},{"src":"/demo/house.jpg","position":"60% 90%","zoom":1.6}]$json$::jsonb, '2026-09-30'::timestamptz),
