  (8, 'Iznajmljivanje', 'Stan', 'Dvosoban stan sa terasom', 'Novi Sad, Grbavica', 45.2472, 19.835, 520, 55, 2, 'Namešten dvosoban stan sa zastakljenom terasom i liftom u zgradi. Dostupan za dugoročan najam.', $json${"Sprat":"4 / 7","Grejanje":"Centralno","Godina izgradnje":2018,"Parking":"Spoljno mesto"}$json$::jsonb, $json$[{"src":"/demo/city.jpg","position":"35% 42%","zoom":2.6},{"src":"/demo/city.jpg","position":"50% 60%","zoom":1},{"src":"/demo/city.jpg","position":"93% 38%","zoom":2.6},{"src":"/demo/city.jpg","position":"54% 42%","zoom":2.6},{"src":"/demo/city.jpg","position":"70% 92%","zoom":2.2}]$json$::jsonb, '2026-10-25'::timestamptz),
  (9, 'Iznajmljivanje', 'Kuća', 'Kuća sa baštom', 'Beograd, Zemun', 44.8444, 20.4124, 900, 120, 4, 'Nameštena kuća sa baštom i garažom, u mirnom naselju. Pogodna za porodicu koja želi više prostora.', $json${"Spratnost":"Pr + 1","Grejanje":"Etažno na gas","Godina izgradnje":2015,"Parking":"Garaža"}$json$::jsonb, $json$[{"src":"/demo/house.jpg","position":"76% 72%","zoom":2.2},{"src":"/demo/house.jpg","position":"48% 42%","zoom":2},{"src":"/demo/house.jpg","position":"76% 72%","zoom":2.2},{"src":"/demo/house.jpg","position":"28% 78%","zoom":2.2},{"src":"/demo/house.jpg","position":"60% 90%","zoom":1.6}]$json$::jsonb, '2026-10-18'::timestamptz)
